import java.util.*;

class Solution {
    private static final String[] PAD = {"", "", "abc", "def", "ghi", "jkl", "mno", "pqrs", "tuv", "wxyz"};

    public List<String> keypadSpellings(String digits) {
        List<String> out = new ArrayList<>();
        if (digits.isEmpty()) return out;
        go(digits, 0, new StringBuilder(), out);
        return out;
    }

    private void go(String digits, int i, StringBuilder cur, List<String> out) {
        if (i == digits.length()) { out.add(cur.toString()); return; }
        for (char ch : PAD[digits.charAt(i) - '0'].toCharArray()) {
            cur.append(ch);
            go(digits, i + 1, cur, out);
            cur.deleteCharAt(cur.length() - 1);   // undo choice
        }
    }
}

