class Solution:
    def keypadSpellings(self, digits: str) -> List[str]:
        if not digits: return []
        pad = {"2": "abc", "3": "def", "4": "ghi", "5": "jkl", "6": "mno", "7": "pqrs", "8": "tuv", "9": "wxyz"}
        out = []
        def go(i, cur):
            if i == len(digits): out.append(cur); return
            for ch in pad[digits[i]]: go(i + 1, cur + ch)
        go(0, "")
        return out

