function keypadSpellings(digits) {
  if (!digits.length) return [];
  const pad = { 2: "abc", 3: "def", 4: "ghi", 5: "jkl", 6: "mno", 7: "pqrs", 8: "tuv", 9: "wxyz" };
  let res = [""];
  for (const d of digits) res = res.flatMap(p => [...pad[d]].map(c => p + c));
  return res;
}
